import json
nums = json.loads(input())
target = int(input())
seen = {}
for i, value in enumerate(nums):
    other = target - value
    if other in seen:
        print(json.dumps([seen[other], i]))
        break
    seen[value] = i

lc-20.source:
text = input()
stack = []
pairs = {')': '(', ']': '[', '}': '{'}
valid = True
for ch in text:
    if ch in '([{':
        stack.append(ch)
    elif not stack or stack.pop() != pairs[ch]:
        valid = False
        break
print(str(valid and not stack).lower())

